mkdir -p /tmp/pushgate-test && cat > /tmp/pushgate-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g2-1/bot.mjs';

const tokyo = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
// JST = UTC+9 in October. Helper: build Date from a JST wall time on 2026-10-22.
const jst = (h, m, day = 22) => new Date(Date.UTC(2026, 9, day, h - 9, m));
const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });

// --- Quiet hours wrap past midnight (Tokyo 22:00-07:00)
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, jst(23, 30)), no('quiet_hours'));
  assert.deepEqual(g.attempt(tokyo, jst(0, 15)), no('quiet_hours'));
  assert.deepEqual(g.attempt(tokyo, jst(6, 59)), no('quiet_hours'));
  assert.deepEqual(g.attempt(tokyo, jst(21, 59)), ok);
  assert.deepEqual(g.attempt(tokyo, jst(7, 0)), ok);
}

// --- Quiet window not wrapping midnight, different zone, and no quiet config
{
  const g = createPushGate();
  const berlin = { id: 'b1', timeZone: 'Europe/Berlin', quietStart: '13:00', quietEnd: '14:00', dailyCap: 5 };
  const at = (h, m) => new Date(Date.UTC(2026, 9, 22, h - 2, m)); // CEST = UTC+2
  assert.deepEqual(g.attempt(berlin, at(13, 0)), no('quiet_hours'));
  assert.deepEqual(g.attempt(berlin, at(13, 59)), no('quiet_hours'));
  assert.deepEqual(g.attempt(berlin, at(14, 0)), ok);
  const noQuiet = { id: 'n1', timeZone: 'UTC', dailyCap: 5 };
  assert.deepEqual(g.attempt(noQuiet, new Date('2026-10-22T03:00:00Z')), ok);
}

// --- Quiet blocks do not count toward the cap or the gap
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, jst(23, 0)), no('quiet_hours'));
  assert.deepEqual(g.attempt(tokyo, jst(8, 0)), ok); // first real push, no gap issue
}

// --- Daily cap and gap
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, jst(9, 0)), ok);
  assert.deepEqual(g.attempt(tokyo, jst(9, 30)), no('too_soon_after_last_push'));
  assert.deepEqual(g.attempt(tokyo, jst(10, 0)), ok);
  assert.deepEqual(g.attempt(tokyo, jst(11, 0)), ok);
  assert.deepEqual(g.attempt(tokyo, jst(12, 0)), no('daily_cap_reached'));
  // Next local day: cap resets, and gap since 11:00 is long enough.
  assert.deepEqual(g.attempt(tokyo, jst(9, 0, 23)), ok);
}

// --- "Day" is the user's calendar day, not a rolling 24h window.
// Los Angeles (PDT, UTC-7). cap 1. Sent 23:00 Oct 22 local; 00:10 Oct 23 local is a new day.
{
  const g = createPushGate();
  const la = { id: 'la', timeZone: 'America/Los_Angeles', dailyCap: 1 };
  const laAt = (day, h, m) => new Date(Date.UTC(2026, 9, day, h + 7, m));
  assert.deepEqual(g.attempt(la, laAt(22, 23, 0)), ok);
  assert.deepEqual(g.attempt(la, laAt(23, 0, 10)), ok); // 70 min later, new local day
  assert.deepEqual(g.attempt(la, laAt(23, 1, 0)), no('daily_cap_reached'));
}

// --- Per-user and per-gate independence; per-call settings honoured
{
  const g1 = createPushGate();
  const g2 = createPushGate();
  const a = { id: 'a', timeZone: 'UTC', dailyCap: 1 };
  const b = { id: 'b', timeZone: 'UTC', dailyCap: 1 };
  const t = new Date('2026-10-22T12:00:00Z');
  assert.deepEqual(g1.attempt(a, t), ok);
  assert.deepEqual(g1.attempt(b, t), ok);
  assert.deepEqual(g2.attempt(a, t), ok);
  assert.deepEqual(g1.attempt({ ...a, dailyCap: 2 }, new Date('2026-10-22T13:30:00Z')), ok);
}

// --- Cap of 0 blocks everything
{
  const g = createPushGate();
  assert.deepEqual(g.attempt({ id: 'z', timeZone: 'UTC', dailyCap: 0 }, new Date('2026-10-22T12:00:00Z')), no('daily_cap_reached'));
}

// --- Invalid input throws rather than silently allowing
{
  const g = createPushGate();
  assert.throws(() => g.attempt(tokyo, '2026-10-22'), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, quietStart: '25:00' }, jst(12, 0)), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, quietEnd: undefined }, jst(12, 0)), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, timeZone: 'Mars/Olympus' }, jst(12, 0)), RangeError);
}

console.log('all pushgate checks passed');
EOF
